param([Parameter(Mandatory=$true)][string]$Session,[switch]$CleanWorkingTestContainers)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$base=Join-Path $root 'analysis/parallel-aa-receiver';$clean=Join-Path $base 'clean-receiver';$Session=(Resolve-Path $Session).Path
if(-not$Session.StartsWith($base+[IO.Path]::DirectorySeparatorChar)){throw 'Session must be inside project analysis'}
$build=(Get-Content "$Session/second-final-build.txt" -Raw).Trim();$first=(Get-Content "$Session/first-final-build.txt" -Raw).Trim();$r=Get-Content "$build/build-validation.json" -Raw|ConvertFrom-Json
foreach($f in @($r.sourceHashes)+@($r.testHashes)){if((Get-FileHash $f.Path).Hash-ne$f.Hash){throw 'Untested final source'}}
foreach($snapshot in @('apks-before.json','live-before.json','source-tests-before.json')){foreach($f in (Get-Content "$Session/$snapshot" -Raw|ConvertFrom-Json)){if((Get-FileHash $f.Path).Hash-ne$f.Hash){throw "Protected baseline changed: $($f.Path)"}}}
if($r.sourceClasses-ne57-or$r.DEX_SHA256-ne'2FDBC63F2F9D63B764697D311AF89D460AE6B8E14B0FADABA9C9339F7FE7C235'){throw 'Unexpected foundation binary change'}
& "$PSScriptRoot/Compare-RdxProtocolBuilds.ps1" -First $first -Second $build -Output "$Session/foundation-reproducibility.json"|Out-Null
function Tree([string]$p){$p=(Resolve-Path $p).Path;return @(Get-ChildItem -LiteralPath $p -Recurse -File|ForEach-Object {$_.FullName.Substring($p.Length)+'='+(Get-FileHash $_.FullName).Hash}|Sort-Object)}
foreach($dir in @('session-transcripts','honda-media-transcripts','video-data-transcripts','secure-body-transcripts')){if(@(Compare-Object (Tree "$first/$dir") (Tree "$build/$dir")).Count){throw 'Receiver transcript payload differs'}}
if(@(Compare-Object (Tree "$Session/baseline-real-tls") (Tree "$Session/final-real-tls")).Count){throw 'Desktop TLS semantic outputs differ'}
$det=[long]0;$prop=[long]0;$rows=@();$transcripts=0
foreach($file in @('test-results.txt','protocol-test-results.txt','independent-test-results.txt','session-test-results.txt','honda-media-test-results.txt','video-data-test-results.txt','secure-body-test-results.txt','api22-provider-model-test-results.txt','api22-shadow-test-results.txt')){$line=Get-Content "$build/$file" -Tail 1;if($line-notmatch'^RESULT PASS'){throw 'Suite not passed'};$d=[regex]::Match($line,'\b(?:deterministic|tests)=(\d+)');$p=[regex]::Match($line,'\bpropertyChecks=(\d+)');$count=if($d.Success){[long]$d.Groups[1].Value}else{0};$properties=if($p.Success){[long]$p.Groups[1].Value}else{0};$det+=$count;$prop+=$properties;$rows+=[pscustomobject]@{suite=$file;deterministic=$count;properties=$properties;result=$line}}
$tls=Get-Content "$Session/final-real-tls/test-results.txt" -Tail 1;if($tls-notmatch'^RESULT PASS'){throw 'Real TLS did not pass'};$det+=[long]([regex]::Match($tls,'\bdeterministic=(\d+)').Groups[1].Value);$prop+=[long]([regex]::Match($tls,'\bpropertyChecks=(\d+)').Groups[1].Value)
foreach($dir in @('session-transcripts','honda-media-transcripts','video-data-transcripts','secure-body-transcripts')){$transcripts+=@(Get-ChildItem "$build/$dir" -File -Filter *.txt|Where-Object Name -ne 'clip-metadata.txt').Count};$transcripts+=@(Get-ChildItem "$Session/final-real-tls" -File|Where-Object Name -ne 'test-results.txt').Count
$rows|ConvertTo-Json|Set-Content "$Session/suite-totals.json"
$qualified=Get-Content "$base/api22-tls-qualifier/FROZEN.json" -Raw|ConvertFrom-Json;if((Get-FileHash (Join-Path $root $qualified.path)).Hash-ne$qualified.sha256){throw 'Frozen qualifier differs'}
$functional=Get-Content "$Session/qualifier-bidirectional-desktop/results.json" -Raw|ConvertFrom-Json;if(-not$functional.complete-or@($functional.tests.PSObject.Properties|Where-Object Value -ne 'PASS').Count){throw 'Qualifier functional group failed'}
$old=Get-Content "$Session/final-validation.json" -Raw|ConvertFrom-Json;if($old.api22ExternalMethods-ne166){throw 'Receiver reference count changed'}
$m5Path='analysis/parallel-aa-receiver/m5-permission/build/20261023-180320-335/rdx-m5-permission-0.2.0-m5-single-port-300s-development.apk';$m5=(Get-FileHash (Join-Path $root $m5Path)).Hash;if($m5-ne'A22E96490B9557AFF022893A8B8B7A08BB13CEC236E52704CDDAFA90A8EE8F40'){throw 'Frozen M5 changed'}
if($CleanWorkingTestContainers){$removed=@();foreach($name in @('test-credentials','fixture-credentials')){$dir=Join-Path $Session $name;if(Test-Path $dir){$dir=(Resolve-Path $dir).Path;if(-not$dir.StartsWith($Session+[IO.Path]::DirectorySeparatorChar)){throw 'Unsafe cleanup path'};foreach($f in Get-ChildItem -LiteralPath $dir -File -Filter *.p12){if($f.Name-notin@('root.p12','other-root.p12','root-trust.p12','other-root-trust.p12','client.p12','server.p12','expired.p12','future.p12','other-client.p12')){throw 'Unexpected container'};$removed+=Get-FileHash $f.FullName;Remove-Item -LiteralPath $f.FullName}}};if($removed.Count){[ordered]@{deleted=$removed;count=$removed.Count;retained='PUBLIC TEST PKCS8 leaf assets intentionally remain packaged for reproducibility; no CA private keys packaged';secureErasureClaim=$false}|ConvertTo-Json -Depth 5|Set-Content "$Session/working-credential-cleanup.json"}}
$result=[ordered]@{schemaVersion=1;date='2026-10-25';scope='OFFLINE FREEZE; no ADB/vehicle/phone/physical USB/Honda JNI/credentials/decoder execution';firmware='D.1.6.4 from last live evidence';targetAndroid=@{release='5.1.1';API=22;ABI='armeabi-v7a';lastLiveFingerprint='Acura/gen1CBD_HS/gen1CBD_HS:5.1.1/LMY48P/14:user/release-keys';savedSystemFingerprint='Acura/gen1CBD_HS/gen1CBD_HS:5.1.1/LMY48P/168:user/release-keys';providerParity='UNVERIFIED across saved/live builds'};factoryAA=@{package='com.honda.androidauto.projection.sink';version='5.1.1-14';versionCode=22;path='/system/app/AndroidAuto/AndroidAuto.apk';lastLiveSHA256='F9E976F44853C9DB7C8FF5A8610C10CAF1E0B4D1E5BE0886F4F52505C5348146';currentVehicleQueried=$false;preservation='No factory modifications; live reports unchanged'};milestones=@{M4='PASS';M5original='INCONCLUSIVE: harness expired before phone';M5retry='READY/FROZEN; not executed';M6='DISABLED UNTIL M5 PASS + separate authorization';M7='OFFLINE FOUNDATION ONLY'};frozenM5=@{path=$m5Path;sha256=$m5;windowSeconds=300};qualifier=$qualified;receiver=@{modules=57;definedClasses=$r.definedClasses.Count;deterministic=$det;propertyAssertions=$prop;independentFixtures=@(Get-ChildItem "$clean/test-fixtures" -Recurse -File -Filter *.bin).Count;semanticTranscripts=$transcripts;transcriptSupportFiles=7;DEX=$r.DEX_SHA256;DEXpath=(Join-Path $build 'dex/classes.dex').Substring($root.Length+1);externalAPI22Methods=166;Java7='PASS';D8min22='PASS';API22runtime='D: RUNTIME TEST UNAVAILABLE';desktopProvider='SunJSSE memory TLS1.2 / TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256';furthest='REAL_TLS_ABSTRACT_INPUT_ACCEPTED';productionSource='UNCHANGED';priorTests='UNCHANGED'};modelCoverage=@{priorProviderSequences=10000;newShadowSequences=25000;newShadowAssertions=810078;newShadowSeed=154560618838757413;desktopTLSCases=10000;desktopAACases=10000;qualifierMechanicsCases=$functional.metrics.randomMechanicsCases;qualifierAACases=$functional.metrics.randomAACases;qualifierSemanticGroups=$functional.tests.PSObject.Properties.Name.Count;api22RuntimeCases=0};protocol=@{outerHeader='PLAINTEXT; channel/flags/BE16 ciphertext length/FIRST BE32 plaintext logical total';encryptedFlag=8;fragmentPlaintextBytes=16128;controlFlagNotChannelZero=$true;startup='Version plaintext ->0003 handshake carrier -> verify -> plaintext0004 AuthResponse -> encrypted ordinary traffic';mediaSetup='8000 PHONE->HU field1 codec3 H264';mediaConfig='8003 HU->PHONE WAIT1 READY2';ack='8004 flow accounting only; not decoded/displayed';mediaData='0000 PHONE->HU BE64 raw timestamp + opaque bytes';codecConfig='0001 PHONE->HU opaque bytes no timestamp'};profiles=@{conservative=@{active='1280x688';dpi=229;fps=60;bytes='08 02 10 01 18 00 20 20 28 e5 01'};experimental=@{optIn=$true;nominal='1920x1080';margins='0/360 total';dpi=229;fps=30;conceptualActive='1920x720';bytes='08 03 10 02 18 00 20 e8 02 28 e5 01';cropPlacement='UNSPECIFIED';touchOffset='UNSPECIFIED'}};unknowns=@('Actual API22 provider completion/residue and close behavior','Provider parity with last live build14','Phone credential/trust/version acceptance','USB permission/ownership and stock contention','Phone AU boundaries and timestamp units','Exact ACK scheduling and reconfiguration','Phone experimental encoded raster/SPS/crop','Real TI decode/render/display','True touchpad transform');historicalAPKs=@{count=69;unchanged=$true};liveReportsUnchanged=$true;nextLive='M5 RETRY ONLY';M6enabled=$false;broadOfflineArchitecture='NOT JUSTIFIED without new runtime/live evidence';integrityManifest='analysis/parallel-aa-receiver/PROJECT-INTEGRITY.json';session=$Session.Substring($root.Length+1);noLiveTaskExecuted=$true}
$result|ConvertTo-Json -Depth 12|Set-Content "$base/PROJECT-STATE.json";$result|ConvertTo-Json -Depth 12|Set-Content "$Session/freeze-summary.json"
Write-Output "FREEZE validated modules57 deterministic=$det properties=$prop fixtures=$($result.receiver.independentFixtures) transcripts=$transcripts; Android runtime0"
